//! A faithful re-implementation of `std::stof`.
//!
//! `std::stof` is a thin wrapper over C's `strtof`: it skips leading
//! whitespace, accepts decimal, hexadecimal, `inf[inity]` and `nan[(chars)]`
//! forms, ignores any trailing garbage, throws `std::invalid_argument` when no
//! conversion could be performed and `std::out_of_range` when `strtof` reports
//! `ERANGE` (overflow, or a result that underflows below `FLT_MIN`).

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StofError {
    /// Nothing convertible at the head of the string.
    Invalid,
    /// `strtof` set `ERANGE`.
    OutOfRange,
}

impl StofError {
    /// The C++ exception class name, as printed by `std::terminate`.
    pub fn exception_name(self) -> &'static str {
        match self {
            StofError::Invalid => "std::invalid_argument",
            StofError::OutOfRange => "std::out_of_range",
        }
    }
}

pub fn stof(s: &str) -> Result<f32, StofError> {
    match strtof(s.as_bytes()) {
        None => Err(StofError::Invalid),
        Some(Parsed { erange: true, .. }) => Err(StofError::OutOfRange),
        Some(Parsed { value, .. }) => Ok(value),
    }
}

struct Parsed {
    value: f32,
    erange: bool,
}

#[inline]
fn is_space(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

#[inline]
fn lower(b: u8) -> u8 {
    b | 0x20
}

fn starts_with_ci(s: &[u8], word: &[u8]) -> bool {
    s.len() >= word.len() && s[..word.len()].iter().zip(word).all(|(a, b)| lower(*a) == *b)
}

/// `strtof`, minus the `endptr` output (the caller never inspects it).
/// Returns `None` when no conversion could be performed.
fn strtof(s: &[u8]) -> Option<Parsed> {
    let mut i = 0;
    while i < s.len() && is_space(s[i]) {
        i += 1;
    }

    let mut negative = false;
    if i < s.len() && (s[i] == b'+' || s[i] == b'-') {
        negative = s[i] == b'-';
        i += 1;
    }
    let rest = &s[i..];

    if starts_with_ci(rest, b"infinity") || starts_with_ci(rest, b"inf") {
        let v = if negative {
            f32::NEG_INFINITY
        } else {
            f32::INFINITY
        };
        return Some(Parsed {
            value: v,
            erange: false,
        });
    }
    if starts_with_ci(rest, b"nan") {
        let v = if negative { -f32::NAN } else { f32::NAN };
        return Some(Parsed {
            value: v,
            erange: false,
        });
    }

    if rest.len() >= 2 && rest[0] == b'0' && lower(rest[1]) == b'x' {
        if let Some(p) = parse_hex(&rest[2..], negative) {
            return Some(p);
        }
        // "0x" with no hex digits: the longest valid prefix is just "0".
        return Some(Parsed {
            value: if negative { -0.0 } else { 0.0 },
            erange: false,
        });
    }

    parse_decimal(rest, negative)
}

/// Split off a run of ASCII digits.
fn take_digits(s: &[u8]) -> (&[u8], &[u8]) {
    let n = s.iter().take_while(|b| b.is_ascii_digit()).count();
    (&s[..n], &s[n..])
}

/// Parse the optional `e[+-]ddd` / `p[+-]ddd` suffix. Returns the exponent and
/// the remainder; the suffix is only consumed when at least one digit follows.
fn take_exponent(s: &[u8], marker: u8) -> i64 {
    if s.is_empty() || lower(s[0]) != marker {
        return 0;
    }
    let mut j = 1;
    let mut neg = false;
    if j < s.len() && (s[j] == b'+' || s[j] == b'-') {
        neg = s[j] == b'-';
        j += 1;
    }
    let (digits, _) = take_digits(&s[j..]);
    if digits.is_empty() {
        return 0;
    }
    // Saturate: anything beyond a few hundred is already ±inf or 0.
    let mut exp: i64 = 0;
    for d in digits {
        exp = exp * 10 + i64::from(d - b'0');
        if exp > 1_000_000 {
            break;
        }
    }
    if neg {
        -exp
    } else {
        exp
    }
}

fn parse_decimal(s: &[u8], negative: bool) -> Option<Parsed> {
    let (int_digits, after_int) = take_digits(s);
    let (frac_digits, after_frac) = if !after_int.is_empty() && after_int[0] == b'.' {
        take_digits(&after_int[1..])
    } else {
        (&after_int[..0], after_int)
    };
    if int_digits.is_empty() && frac_digits.is_empty() {
        return None;
    }

    let exp = take_exponent(after_frac, b'e');

    // Hand the normalised literal to the standard library, which converts
    // decimal to `f32` with correct rounding.
    let mut literal = String::with_capacity(int_digits.len() + frac_digits.len() + 24);
    literal.push_str(std::str::from_utf8(int_digits).unwrap_or("0"));
    literal.push('.');
    literal.push_str(std::str::from_utf8(frac_digits).unwrap_or("0"));
    if literal.starts_with('.') {
        literal.insert(0, '0');
    }
    if literal.ends_with('.') {
        literal.push('0');
    }
    let exp = exp.clamp(-1_000_000, 1_000_000);
    literal.push('e');
    literal.push_str(&exp.to_string());

    let magnitude: f32 = literal.parse().unwrap_or(0.0);
    let all_zero = int_digits.iter().chain(frac_digits).all(|d| *d == b'0');
    Some(finish(magnitude, negative, all_zero))
}

/// Split off a run of ASCII hex digits.
fn take_hex_digits(s: &[u8]) -> (&[u8], &[u8]) {
    let n = s.iter().take_while(|b| b.is_ascii_hexdigit()).count();
    (&s[..n], &s[n..])
}

fn parse_hex(s: &[u8], negative: bool) -> Option<Parsed> {
    let hex_run = take_hex_digits;

    let (int_digits, after_int) = hex_run(s);
    let (frac_digits, after_frac) = if !after_int.is_empty() && after_int[0] == b'.' {
        hex_run(&after_int[1..])
    } else {
        (&after_int[..0], after_int)
    };
    if int_digits.is_empty() && frac_digits.is_empty() {
        return None;
    }

    let p_exp = take_exponent(after_frac, b'p');

    // value == mantissa * 2^exp2, with `mantissa` the concatenated hex digits.
    let significant: Vec<u8> = int_digits
        .iter()
        .chain(frac_digits)
        .map(|b| hex_value(*b))
        .skip_while(|d| *d == 0)
        .collect();
    let exp2 = p_exp - 4 * frac_digits.len() as i64;

    if significant.is_empty() {
        return Some(Parsed {
            value: if negative { -0.0 } else { 0.0 },
            erange: false,
        });
    }

    // Short-circuit magnitudes that cannot possibly round into range, so the
    // exact expansion below never has to chew through a huge exponent.
    let approx_log2 = 4 * significant.len() as i64 + exp2;
    if approx_log2 > 160 {
        return Some(finish(f32::INFINITY, negative, false));
    }
    if approx_log2 < -200 {
        return Some(finish(0.0, negative, false));
    }

    // Exact decimal expansion: m * 2^e == (m * 5^-e) * 10^e for e < 0.
    let mut digits = BigDec::zero();
    for d in &significant {
        digits.mul_add_small(16, u32::from(*d));
    }
    let dec_exp = if exp2 >= 0 {
        for _ in 0..exp2 {
            digits.mul_add_small(2, 0);
        }
        0
    } else {
        for _ in 0..-exp2 {
            digits.mul_add_small(5, 0);
        }
        exp2
    };

    let literal = format!("{}e{}", digits, dec_exp);
    let magnitude: f32 = literal.parse().unwrap_or(0.0);
    Some(finish(magnitude, negative, false))
}

/// Apply the sign and decide whether `strtof` would have set `ERANGE`.
fn finish(magnitude: f32, negative: bool, all_zero: bool) -> Parsed {
    let erange = if magnitude.is_infinite() {
        true
    } else {
        // glibc reports underflow for any non-zero input that lands on zero or
        // on a subnormal.
        !all_zero && magnitude < f32::MIN_POSITIVE
    };
    Parsed {
        value: if negative { -magnitude } else { magnitude },
        erange,
    }
}

fn hex_value(b: u8) -> u8 {
    match b {
        b'0'..=b'9' => b - b'0',
        _ => lower(b) - b'a' + 10,
    }
}

/// A minimal big decimal integer: just enough to expand a hex significand.
struct BigDec {
    /// Little-endian decimal digits; empty means zero.
    digits: Vec<u8>,
}

impl BigDec {
    fn zero() -> Self {
        BigDec { digits: Vec::new() }
    }

    fn mul_add_small(&mut self, mul: u32, add: u32) {
        let mut carry = add;
        for d in self.digits.iter_mut() {
            let v = u32::from(*d) * mul + carry;
            *d = (v % 10) as u8;
            carry = v / 10;
        }
        while carry > 0 {
            self.digits.push((carry % 10) as u8);
            carry /= 10;
        }
    }
}

impl std::fmt::Display for BigDec {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        if self.digits.is_empty() {
            return f.write_str("0");
        }
        for d in self.digits.iter().rev() {
            write!(f, "{}", d)?;
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn accepts_what_strtof_accepts() {
        assert_eq!(stof("0.5"), Ok(0.5));
        assert_eq!(stof(".5"), Ok(0.5));
        assert_eq!(stof("+3"), Ok(3.0));
        assert_eq!(stof("-.5e1"), Ok(-5.0));
        assert_eq!(stof("1abc"), Ok(1.0));
        assert_eq!(stof("  1.5xyz"), Ok(1.5));
        assert_eq!(stof("1_0"), Ok(1.0));
        assert_eq!(stof("0x1p4"), Ok(16.0));
        assert_eq!(stof("0x1.8p1"), Ok(3.0));
        assert_eq!(stof("INFINITY"), Ok(f32::INFINITY));
        assert!(stof("nan(123)").unwrap().is_nan());
        assert_eq!(stof("3.4e38"), Ok(3.4e38));
    }

    #[test]
    fn rejects_what_strtof_rejects() {
        assert_eq!(stof("abc"), Err(StofError::Invalid));
        assert_eq!(stof(""), Err(StofError::Invalid));
        assert_eq!(stof("e5"), Err(StofError::Invalid));
        assert_eq!(stof("1e999"), Err(StofError::OutOfRange));
        assert_eq!(stof("1e-999"), Err(StofError::OutOfRange));
        assert_eq!(stof("1e-46"), Err(StofError::OutOfRange));
        assert_eq!(stof("1e-44"), Err(StofError::OutOfRange));
        assert_eq!(stof("3.5e38"), Err(StofError::OutOfRange));
        assert_eq!(stof("0.0"), Ok(0.0));
    }
}
